args.command:
cat > /tmp/fanin.go << 'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type Decl struct {
	Key      string
	Name     string
	Recv     string
	PkgPath  string
	PkgName  string
	File     string
	IsMethod bool
	Line     int
}

type FileData struct {
	Path     string
	PkgName  string
	PkgPath  string
	Internal bool
	File     *ast.File
	Imports  map[string]string // local name -> import path
}

func main() {
	root := "/bench/repo"
	fset := token.NewFileSet()
	var files []*FileData

	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			base := info.Name()
			if base == "vendor" || base == ".git" || base == "node_modules" || base == "web" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		// include tests for call counting
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			fmt.Fprintf(os.Stderr, "parse error %s: %v\n", path, err)
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		dir := filepath.Dir(rel)
		pkgPath := "github.com/usememos/memos"
		if dir != "." {
			pkgPath = "github.com/usememos/memos/" + filepath.ToSlash(dir)
		}
		fd := &FileData{
			Path:     rel,
			PkgName:  f.Name.Name,
			PkgPath:  pkgPath,
			Internal: strings.HasPrefix(filepath.ToSlash(rel), "internal/"),
			File:     f,
			Imports:  map[string]string{},
		}
		for _, imp := range f.Imports {
			ip := strings.Trim(imp.Path.Value, `"`)
			local := ""
			if imp.Name != nil {
				local = imp.Name.Name
			} else {
				parts := strings.Split(ip, "/")
				local = parts[len(parts)-1]
			}
			fd.Imports[local] = ip
		}
		files = append(files, fd)
		return nil
	})
	if err != nil {
		panic(err)
	}

	decls := map[string]*Decl{}
	// also index by pkgPath + name for functions, and pkgPath + recv + name for methods
	for _, fd := range files {
		if !fd.Internal {
			continue
		}
		if strings.HasSuffix(fd.Path, "_test.go") {
			continue // declarations in tests don't count as the target
		}
		ast.Inspect(fd.File, func(n ast.Node) bool {
			fn, ok := n.(*ast.FuncDecl)
			if !ok || fn.Name == nil {
				return true
			}
			name := fn.Name.Name
			if name == "init" || name == "main" {
				return true
			}
			d := &Decl{
				Name:    name,
				PkgPath: fd.PkgPath,
				PkgName: fd.PkgName,
				File:    fd.Path,
				Line:    fset.Position(fn.Pos()).Line,
			}
			if fn.Recv != nil && len(fn.Recv.List) > 0 {
				d.IsMethod = true
				d.Recv = recvTypeName(fn.Recv.List[0].Type)
			}
			if d.IsMethod {
				d.Key = fd.PkgPath + "." + d.Recv + "." + name
			} else {
				d.Key = fd.PkgPath + "." + name
			}
			decls[d.Key] = d
			return true
		})
	}

	// Count call sites
	counts := map[string]int{}
	callers := map[string]map[string]bool{} // unique caller functions
	for k := range decls {
		counts[k] = 0
		callers[k] = map[string]bool{}
	}

	for _, fd := range files {
		ast.Inspect(fd.File, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			pos := fset.Position(call.Pos())
			site := fmt.Sprintf("%s:%d", fd.Path, pos.Line)

			switch fun := call.Fun.(type) {
			case *ast.Ident:
				// same-package function call
				key := fd.PkgPath + "." + fun.Name
				if _, ok := decls[key]; ok {
					counts[key]++
					callers[key][site] = true
				}
			case *ast.SelectorExpr:
				// pkg.Func() or recv.Method()
				if ident, ok := fun.X.(*ast.Ident); ok {
					if ip, isPkg := fd.Imports[ident.Name]; isPkg {
						key := ip + "." + fun.Sel.Name
						if _, ok := decls[key]; ok {
							counts[key]++
							callers[key][site] = true
						}
						return true
					}
				}
				// method call: match all methods with this name in internal
				// We'll count later more carefully; for now count every matching method name
				// This over-counts common names. Record as method-name match.
				mname := fun.Sel.Name
				// only increment methods with this name; if unique, it's reliable
				matches := []*Decl{}
				for _, d := range decls {
					if d.IsMethod && d.Name == mname {
						matches = append(matches, d)
					}
				}
				if len(matches) == 1 {
					counts[matches[0].Key]++
					callers[matches[0].Key][site] = true
				}
				// if multiple, skip for now (ambiguous)
			}
			return true
		})
	}

	type row struct {
		d        *Decl
		calls    int
		nCallers int
	}
	var rows []row
	for k, d := range decls {
		rows = append(rows, row{d, counts[k], len(callers[k])})
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].calls != rows[j].calls {
			return rows[i].calls > rows[j].calls
		}
		return rows[i].d.Key < rows[j].d.Key
	})

	fmt.Println("=== TOP 40 by call-site count (methods only if unique name) ===")
	for i, r := range rows {
		if i >= 40 {
			break
		}
		kind := "func"
		if r.d.IsMethod {
			kind = "meth"
		}
		fmt.Printf("%3d  calls=%3d sites=%3d  %s  %s  %s:%d\n", i+1, r.calls, r.nCallers, kind, r.d.Key, r.d.File, r.d.Line)
	}

	// Also print method name frequency (how many decls share a name)
	fmt.Println("\n=== Method names with multiple decls (ambiguous) ===")
	mcount := map[string]int{}
	for _, d := range decls {
		if d.IsMethod {
			mcount[d.Name]++
		}
	}
	type mn struct {
		n string
		c int
	}
	var mns []mn
	for n, c := range mcount {
		if c > 1 {
			mns = append(mns, mn{n, c})
		}
	}
	sort.Slice(mns, func(i, j int) bool { return mns[i].c > mns[j].c })
	for i, x := range mns {
		if i >= 20 {
			break
		}
		fmt.Printf("  %s x%d\n", x.n, x.c)
	}

	fmt.Printf("\nTotal decls: %d\n", len(decls))
}

func recvTypeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return recvTypeName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.IndexExpr:
		return recvTypeName(t.X)
	default:
		return fmt.Sprintf("%T", e)
	}
}
EOF
cd /tmp && go run fanin.go

