output.value:
package util //nolint:revive // util namespace is intentional for shared helpers

import (
	"crypto/rand"
	"math/big"
	"net/mail"
	"strconv"
	"strings"

	"github.com/google/uuid"
)

// ConvertStringToInt32 converts a string to int32.
func ConvertStringToInt32(src string) (int32, error) {
	parsed, err := strconv.ParseInt(src, 10, 32)
	if err != nil {
		return 0, err
	}
	return int32(parsed), nil
}

// HasPrefixes returns true if the string s has any of the given prefixes.
func HasPrefixes(src string, prefixes ...string) bool {
	for _, prefix := range prefixes {
		if strings.HasPrefix(src, prefix) {
			return true
		}
	}
	return false
}

// ValidateEmail validates the email.
func ValidateEmail(email string) bool {
	if _, err := mail.ParseAddress(email); err != nil {
		return false
	}
	return true
}

func GenUUID() string {
	return uuid.New().String()
}

var letters = []rune("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")

// RandomString returns a random string with length n.
func RandomString(n int) (string, error) {
	var sb strings.Builder
	sb.Grow(n)
	for i := 0; i < n; i++ {
		// The reason for using crypto/rand instead of math/rand is that
		// the former relies on hardware to generate random numbers and
		// thus has a stronger source of random numbers.
		randNum, err := rand.Int(rand.Reader, big.NewInt(int64(len(letters))))
		if err != nil {
			return "", err
		}
		if _, err := sb.WriteRune(letters[randNum.Uint64()]); err != nil {
			return "", err
		}
	}
	return sb.String(), nil
}

// ReplaceString replaces all occurrences of old in slice with new.
func ReplaceString(slice []string, old, new string) []string {
	for i, s := range slice {
		if s == old {
			slice[i] = new
		}
	}
	return slice
}

args.command:
cat > /tmp/fanin.pl << 'ENDSCRIPT'
#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";
my @gofiles;
find({
  wanted => sub {
    return unless /\.go$/;
    my $p = $File::Find::name;
    return if $p =~ m{/\.git/} || $p =~ m{/web/} || $p =~ m{/node_modules/} || $p =~ m{/vendor/};
    push @gofiles, $p;
  },
  no_chdir => 1,
}, $root);

# Parse each file
my @files;
for my $path (@gofiles) {
  open my $fh, "<", $path or die $!;
  my $src = do { local $/; <$fh> };
  close $fh;
  my $rel = $path;
  $rel =~ s{^\Q$root\E/}{};
  my $pkgname = "";
  if ($src =~ /^package\s+(\w+)/m) { $pkgname = $1; }
  my $dir = $rel;
  $dir =~ s{/[^/]+$}{};
  my $pkgpath = $dir eq $rel ? "github.com/usememos/memos" : "github.com/usememos/memos/$dir";
  $pkgpath =~ s{\\}{/}g;

  my %imports;
  # collect imports
  if ($src =~ /import\s*\((.*?)\)/s) {
    my $block = $1;
    for my $line (split /\n/, $block) {
      next if $line =~ /^\s*\/\//;
      if ($line =~ /(?:(\w+)|(\.))\s+"([^"]+)"/ || $line =~ /"([^"]+)"/) {
        my $alias = $1;
        my $dot = $2;
        my $ip = $3 // $1;
        if ($line =~ /"([^"]+)"/) { $ip = $1; }
        if ($line =~ /^\s*(\w+)\s+"/ && $line !~ /^\s*[_]/) {
          $alias = $1 unless $1 eq '';
        } elsif ($line =~ /^\s*\.\s+"/) {
          $alias = ".";
        } else {
          my @parts = split /\//, $ip;
          $alias = $parts[-1];
        }
        $imports{$alias} = $ip;
      }
    }
  } elsif ($src =~ /import\s+(\w+)\s+"([^"]+)"/) {
    $imports{$1} = $2;
  } elsif ($src =~ /import\s+"([^"]+)"/) {
    my @parts = split /\//, $1;
    $imports{$parts[-1]} = $1;
  }

  push @files, {
    path => $rel, full => $path, src => $src, pkgname => $pkgname,
    pkgpath => $pkgpath, imports => \%imports,
    internal => ($rel =~ m{^internal/} ? 1 : 0),
    test => ($rel =~ /_test\.go$/ ? 1 : 0),
  };
}

# Collect declarations from internal non-test
my %decls; # key -> decl
for my $f (@files) {
  next unless $f->{internal};
  next if $f->{test};
  my $src = $f->{src};
  # strip comments roughly for decl scan? keep as-is, func decls are at line start
  my $line = 0;
  for my $ln (split /\n/, $src) {
    $line++;
    if ($ln =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*(?:\[|[({])/) {
      my $recv = $1 // "";
      my $name = $2;
      next if $name eq "init" || $name eq "main";
      my $ismethod = $recv ne "";
      my $recvtype = "";
      if ($ismethod) {
        $recvtype = $recv;
        $recvtype =~ s/\s+/ /g;
        if ($recvtype =~ /\*?([A-Za-z_][A-Za-z0-9_]*)/) {
          $recvtype = $1;
        }
      }
      my $key = $ismethod ? "$f->{pkgpath}.$recvtype.$name" : "$f->{pkgpath}.$name";
      $decls{$key} = {
        key => $key, name => $name, recv => $recvtype, ismethod => $ismethod,
        pkgpath => $f->{pkgpath}, pkgname => $f->{pkgname}, file => $f->{path}, line => $line,
      };
    }
  }
}

# Build indexes
my %funcs_by_pkg_name; # pkgpath|name -> key (functions only)
my %methods_by_name; # name -> [keys]
my %func_names_unique; # name -> [keys] for functions
for my $k (keys %decls) {
  my $d = $decls{$k};
  if ($d->{ismethod}) {
    push @{$methods_by_name{$d->{name}}}, $k;
  } else {
    $funcs_by_pkg_name{"$d->{pkgpath}|$d->{name}"} = $k;
    push @{$func_names_unique{$d->{name}}}, $k;
  }
}

my %counts;
my %sites;
for my $k (keys %decls) { $counts{$k} = 0; $sites{$k} = {}; }

# Tokenize-ish call finder
for my $f (@files) {
  my $src = $f->{src};
  # remove block comments and line comments to reduce false positives
  $src =~ s{/\*.*?\*/}{}sg;
  $src =~ s{//.*$}{}mg;
  # remove raw strings and interpreted strings (rough)
