      if ($ismethod && $recv =~ /\*?([A-Za-z_][A-Za-z0-9_]*)(?:\s|$)/) {
        # last ident is the type
        my @ids = ($recv =~ /[A-Za-z_][A-Za-z0-9_]*/g);
        $recvtype = $ids[-1] if @ids;
      }
      my $key = $ismethod ? "$f->{pkgpath}.$recvtype.$name" : "$f->{pkgpath}.$name";
      $decls{$key} = {
        key => $key, name => $name, recv => $recvtype, ismethod => $ismethod,
        pkgpath => $f->{pkgpath}, pkgname => $f->{pkgname}, file => $f->{path}, line => $line,
      };
    }
  }
}

my %funcs_by_pkg_name;
my %methods_by_name;
for my $k (keys %decls) {
  my $d = $decls{$k};
  if ($d->{ismethod}) {
    push @{$methods_by_name{$d->{name}}}, $k;
  } else {
    $funcs_by_pkg_name{"$d->{pkgpath}|$d->{name}"} = $k;
  }
}

my %counts;
my %sites;
for my $k (keys %decls) { $counts{$k} = 0; $sites{$k} = {}; }

for my $f (@files) {
  my $src = $f->{src};
  $src =~ s{/\*.*?\*/}{}sg;
  $src =~ s{//.*$}{}mg;
  $src =~ s/`[^`]*`/""/sg;
  $src =~ s/"(?:\\.|[^"\\])*"/""/g;

  while ($src =~ /(?:(\w+)\s*\.\s*)?(\w+)\s*(?:\[\s*[^\]]*\]\s*)?\(/g) {
    my $left = $1;
    my $name = $2;
    my $pos = $-[0];
    my $prefix = substr($src, 0, $pos);
    my $line = 1 + ($prefix =~ tr/\n//);
    my $site = "$f->{path}:$line";

    my $before = substr($src, 0, $pos);
    if ($before =~ /func\s+(?:\([^)]*\)\s*)?\z/) {
      next;
    }
    next if $name =~ /^(if|for|switch|select|go|defer|return|func|range|make|new|append|len|cap|close|copy|delete|panic|recover|complex|real|imag|min|max)$/;

    if (defined $left && $left ne "") {
      if (exists $f->{imports}{$left}) {
        my $ip = $f->{imports}{$left};
        my $key = $funcs_by_pkg_name{"$ip|$name"};
        if ($key) {
          $counts{$key}++;
          $sites{$key}{$site} = 1;
        }
      } else {
        my $keys = $methods_by_name{$name} || [];
        if (@$keys == 1) {
          $counts{$keys->[0]}++;
          $sites{$keys->[0]}{$site} = 1;
        } elsif (@$keys > 1) {
          my @same = grep { $decls{$_}{pkgpath} eq $f->{pkgpath} } @$keys;
          if (@same == 1) {
            $counts{$same[0]}++;
            $sites{$same[0]}{$site} = 1;
          }
        }
      }
    } else {
      my $key = $funcs_by_pkg_name{"$f->{pkgpath}|$name"};
      if ($key) {
        $counts{$key}++;
        $sites{$key}{$site} = 1;
      }
      if (exists $f->{imports}{"."}) {
        my $ip = $f->{imports}{"."};
        my $k2 = $funcs_by_pkg_name{"$ip|$name"};
        if ($k2) {
          $counts{$k2}++;
          $sites{$k2}{$site} = 1;
        }
      }
    }
  }
}

my @rows;
for my $k (keys %decls) {
  push @rows, [$counts{$k}, scalar(keys %{$sites{$k}}), $decls{$k}];
}
@rows = sort { $b->[0] <=> $a->[0] || $b->[1] <=> $a->[1] || $a->[2]{key} cmp $b->[2]{key} } @rows;

print "=== TOP 50 by call-site count ===\n";
for my $i (0..49) {
  last if $i > $#rows;
  my ($c, $s, $d) = @{$rows[$i]};
  my $kind = $d->{ismethod} ? "meth" : "func";
  printf "%3d  calls=%3d uniq_sites=%3d  %-4s  %s  (%s:%d)\n", $i+1, $c, $s, $kind, $d->{key}, $d->{file}, $d->{line};
}

print "\n=== Ambiguous method names (not fully counted) ===\n";
for my $n (sort { @{$methods_by_name{$b}} <=> @{$methods_by_name{$a}} } keys %methods_by_name) {
  my $ks = $methods_by_name{$n};
  next unless @$ks > 1;
  printf "  %s (%d decls): %s\n", $n, scalar(@$ks), join(", ", @$ks);
}

print "\nTotal decls: ", scalar(keys %decls), "\n";

print "\n=== GenUUID sites ===\n";
for my $k (keys %decls) {
  next unless $decls{$k}{name} eq "GenUUID";
  print "DECL $k calls=$counts{$k}\n";
  print "  $_\n" for sort keys %{$sites{$k}};
}

print "\n=== ConvertStringToInt32 sites ===\n";
for my $k (keys %decls) {
  next unless $decls{$k}{name} eq "ConvertStringToInt32";
  print "DECL $k calls=$counts{$k}\n";
  print "  $_\n" for sort keys %{$sites{$k}};
}
ENDSCRIPT
perl /tmp/fanin.pl

