# For every unique function name declared in internal (non-method), count call-like occurrences
# excluding the declaration line. Also do unique method names that look distinctive (len>=8 or unexported).

perl -e '
use strict;
my %funcs;
my %methods;
open my $find, "-|", "find /bench/repo/internal -name *.go ! -name *_test.go" or die;
while (my $f = <$find>) {
  chomp $f;
  open my $fh, "<", $f or die;
  my $pkg = "";
  while (<$fh>) {
    $pkg = $1 if /^package\s+(\w+)/;
    if (/^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*(?:\[|[({])/) {
      my ($recv, $name) = ($1, $2);
      next if $name eq "init" or $name eq "main";
      if ($recv) { $methods{$name}++; }
      else { $funcs{$name}++; }
    }
  }
}
close $find;

# count across repo
my @files;
open $find, "-|", "find /bench/repo -name *.go ! -path */.git/* ! -path */web/*" or die;
while (<$find>) { chomp; push @files, $_; }
close $find;

sub count_name {
  my ($name) = @_;
  my $n = 0;
  my $decl = 0;
  for my $f (@files) {
    open my $fh, "<", $f or next;
    while (<$fh>) {
      next if m{^\s*//};
      if (/\b\Q$name\E\s*\(/) {
        if (/^func\s/) { $decl++; }
        else { $n++; }
      }
    }
  }
  return ($n, $decl);
}

my @rows;
for my $name (keys %funcs) {
  next if $funcs{$name} != 1; # skip name collisions among funcs
  my ($n, $d) = count_name($name);
  push @rows, [$n, $name, "func", $funcs{$name}, $d];
}
for my $name (keys %methods) {
  next if $methods{$name} != 1;
  # skip very common short exported names
  next if $name =~ /^(New|Stop|Start|Send|Next|Get|Set|Len|Less|Swap|Field|Register|Format|Parse|Kind|Dump|Close|Read|Write|String|Error|Unwrap)$/;
  my ($n, $d) = count_name($name);
  push @rows, [$n, $name, "meth", $methods{$name}, $d];
}
@rows = sort { $b->[0] <=> $a->[0] } @rows;
print "count  kind  name  (funcdecls=$funcs{$_} methoddecls)\n";
for my $i (0..35) {
  last if $i > $#rows;
  my ($n,$name,$kind,$decls,$d) = @{$rows[$i]};
  printf "%3d  %-4s  %-30s  unique_decls=%d  decl_lines=%d\n", $n, $kind, $name, $decls, $d;
}
'

