echo '===== matches in scheduler ====='
grep -n 'matches(' /bench/repo/internal/scheduler/*.go
echo
echo '===== NewEngine exact call count minus decl ====='
grep -rn --include='*.go' 'NewEngine(' /bench/repo --exclude-dir=web --exclude-dir=.git | grep -v 'func NewEngine'
echo
