# Render method on Program
grep -rn --include='*.go' '\.Render(' /bench/repo --exclude-dir=web --exclude-dir=.git | grep -E 'filter|program|stmt' | head -20
echo
echo '===== AppendConditions ====='
grep -rn --include='*.go' 'AppendConditions(' /bench/repo --exclude-dir=web --exclude-dir=.git
echo
echo '===== jsonArrayExpr ====='
grep -rn --include='*.go' 'jsonArrayExpr(' /bench/repo --exclude-dir=web --exclude-dir=.git | wc -l
echo
echo '===== Validate method calls in profile ====='
grep -rn --include='*.go' 'profile.*Validate\|p\.Validate\|cfg\.Validate\|instanceProfile.Validate' /bench/repo --exclude-dir=web --exclude-dir=.git | head
echo
# Count unique calling functions for CompileToStatement
echo '===== CompileToStatement context (func names) ====='
perl -e '
open my $find, "-|", "find /bench/repo -name \"*.go\"" or die;
my @files;
while (<$find>) { chomp; next if m{/web/}||m{/\.git/}; push @files, $_; }
my $callers = 0;
my $sites = 0;
for my $f (@files) {
  open my $fh, "<", $f or next;
  my $src = do { local $/; <$fh> };
  my $cur = "?";
  my $line = 0;
  for my $ln (split /\n/, $src) {
    $line++;
    if ($ln =~ /^func\s+(?:\([^)]+\)\s+)?([A-Za-z0-9_]+)/) { $cur = $1; }
    if ($ln =~ /CompileToStatement\s*\(/ && $ln !~ /^func\s/) {
      $sites++;
      print "$f:$line in $cur\n";
    }
  }
}
print "sites=$sites\n";
'

